window.docContents[95].resolve({"/releases/#release-v4___35___0":{"contents":"\n\n* Marginalia in the manual genre previously had problems when placed in certain boxes, such as tables. Now, they are hoisted up to a level where they can be correctly displayed.\nA consequence of this is that, on mobile, marginalia are now shown as popovers instead of toggling text regions.\n (#990)* Errata tests can now be run directly from the InfoView using a dedicated widget.\n (#959)\n\n","context":"Writing Documentation in Lean with Verso\u0009Release Notes","header":"Verso 4.35.0 (in development)","id":"/releases/#release-v4___35___0"}});